import { useCallback, useEffect, useMemo, useState } from "react";

interface PanelProps { projectId: string }
interface Artifact { id:number; kind:string; format:string; name:string; size_bytes:number; storage_file_id?:string }
interface Check { code:string; severity:"error"|"warning"; message:string; object_ids?:string[] }
interface Validation { status:string; errors:number; warnings:number; report:{ checks:Check[] } }
interface Revision { id:number; number:number; source_sha256:string; definition:Definition }
interface Design { id:number; name:string; status:string; current_revision_id:number; current_revision?:Revision; validation?:Validation; artifacts?:Artifact[]; updated_at:string }
interface Point { x_nm:number; y_nm:number }
interface Definition {
  schema:string; name?:string;
  board:{ width_nm:number; height_nm:number; layers:{id:string;kind:string;order:number}[] };
  rules:{ min_clearance_nm:number; min_trace_width_nm:number; min_edge_clearance_nm:number };
  components:{ id:string;designator:string;name:string;value?:string;mpn?:string;footprint?:string;position:{x_nm:number;y_nm:number;rotation_udeg:number;side:string};pins?:unknown[] }[];
  nets:{id:string;name:string;nodes?:unknown[]}[];
  traces:{id:string;net_id:string;layer:string;width_nm:number;points:Point[]}[];
  vias:{id:string;net_id:string;x_nm:number;y_nm:number;diameter_nm:number;drill_nm:number;from_layer:string;to_layer:string}[];
}

const API="/api/apps/pcb/api";
const TEMPLATE:Definition={schema:"apteva-pcb/v1",name:"Controller board",board:{width_nm:50000000,height_nm:30000000,layers:[{id:"F.Cu",kind:"copper",order:0},{id:"B.Cu",kind:"copper",order:1}]},rules:{min_clearance_nm:200000,min_trace_width_nm:200000,min_edge_clearance_nm:250000},components:[{id:"u1",designator:"U1",name:"Microcontroller",value:"RP2040",mpn:"RP2040",footprint:"QFN-56",position:{x_nm:25000000,y_nm:15000000,rotation_udeg:0,side:"front"},pins:[{id:"1",number:"1",name:"IO0",electrical_type:"bidirectional",pad:"1"}]},{id:"j1",designator:"J1",name:"Connector",value:"USB-C",footprint:"USB-C-16P",position:{x_nm:5000000,y_nm:15000000,rotation_udeg:90000000,side:"front"},pins:[{id:"1",number:"1",name:"D+",electrical_type:"bidirectional",pad:"1"}]}],nets:[{id:"usb-dp",name:"USB_D+",nodes:[{component_id:"u1",pin_id:"1"},{component_id:"j1",pin_id:"1"}]}],traces:[{id:"usb-dp-1",net_id:"usb-dp",layer:"F.Cu",width_nm:250000,points:[{x_nm:5000000,y_nm:15000000},{x_nm:25000000,y_nm:15000000}]}],vias:[]};
function url(path:string,projectId:string){return `${API}${path}${path.includes("?")?"&":"?"}project_id=${encodeURIComponent(projectId)}`}
async function request(path:string,projectId:string,init?:RequestInit){const response=await fetch(url(path,projectId),{credentials:"same-origin",...init,headers:{"Content-Type":"application/json",...(init?.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||response.statusText);return body}
const mm=(nm:number)=>nm/1e6;

export default function PCBPanel({projectId}:PanelProps){
  const [designs,setDesigns]=useState<Design[]>([]),[selectedId,setSelectedId]=useState<number|null>(null),[design,setDesign]=useState<Design|null>(null);
  const [source,setSource]=useState(JSON.stringify(TEMPLATE,null,2)),[newName,setNewName]=useState("Controller board"),[note,setNote]=useState("");
  const [tab,setTab]=useState<"board"|"source">("board"),[busy,setBusy]=useState(""),[error,setError]=useState("");
  const parsed=useMemo(()=>{try{return JSON.parse(source) as Definition}catch{return null}},[source]);
  const loadDesigns=useCallback(async()=>{const body=await request("/designs?status=all",projectId);setDesigns(body.designs||[]);if(!selectedId&&body.designs?.length)setSelectedId(body.designs[0].id)},[projectId,selectedId]);
  const loadDesign=useCallback(async(id:number)=>{const body=await request(`/designs/${id}`,projectId);setDesign(body.design);setSource(JSON.stringify(body.design.current_revision?.definition||TEMPLATE,null,2))},[projectId]);
  useEffect(()=>{loadDesigns().catch(e=>setError(e.message))},[loadDesigns]);useEffect(()=>{if(selectedId)loadDesign(selectedId).catch(e=>setError(e.message))},[selectedId,loadDesign]);
  async function run(label:string,fn:()=>Promise<void>){setBusy(label);setError("");try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy("")}}
  function create(){if(!parsed)return setError("The native PCB JSON is not valid.");run("Creating",async()=>{const body=await request("/designs",projectId,{method:"POST",body:JSON.stringify({name:newName,definition:parsed,note:"Initial native board"})});await loadDesigns();setSelectedId(body.design.id)})}
  function save(){if(!design||!parsed)return setError("Select a design and fix the source JSON first.");run("Saving revision",async()=>{await request(`/designs/${design.id}/revisions`,projectId,{method:"POST",body:JSON.stringify({expected_parent_id:design.current_revision_id,definition:parsed,note})});setNote("");await loadDesign(design.id);await loadDesigns()})}
  function action(name:string,label:string){if(!design)return;run(label,async()=>{await request(`/designs/${design.id}/${name}`,projectId,{method:"POST",body:"{}"});await loadDesign(design.id)})}
  const validation=design?.validation,artifacts=design?.artifacts||[];
  return <div className="pcb-root">
    <header className="pcb-header"><div className="pcb-logo">⌁</div><div><h1>PCB Studio</h1><p>Native circuit + board design · no external ECAD engine</p></div><span className="grow"/><button onClick={()=>action("validate","Validating")} disabled={!design||!!busy}>ERC / DRC</button><button onClick={()=>action("render","Rendering")} disabled={!design||!!busy}>SVG preview</button><button onClick={()=>action("bom","Building BOM")} disabled={!design||!!busy}>BOM</button><button className="primary" onClick={()=>action("release","Creating release")} disabled={!design||!!busy}>Release ZIP</button></header>
    {busy&&<div className="progress"/>}{error&&<div className="error">{error}</div>}
    <div className="pcb-grid">
      <aside className="library"><Label>Boards</Label>{designs.map(d=><button className="design-item" data-active={selectedId===d.id} onClick={()=>setSelectedId(d.id)} key={d.id}><strong>{d.name}</strong><small>{d.status} · r{d.id===design?.id?design.current_revision?.number:"—"}</small></button>)}{!designs.length&&<p className="muted">No boards yet.</p>}<div className="new"><Label>New native board</Label><input value={newName} onChange={e=>setNewName(e.target.value)}/><button className="primary wide" disabled={!parsed||!newName.trim()||!!busy} onClick={create}>Create from editor</button></div></aside>
      <main className="workspace"><div className="tabs"><button data-active={tab==="board"} onClick={()=>setTab("board")}>Board</button><button data-active={tab==="source"} onClick={()=>setTab("source")}>Native source</button><span className="grow"/>{design?.current_revision&&<code>r{design.current_revision.number} · {design.current_revision.source_sha256.slice(0,10)}</code>}</div>{tab==="board"?<BoardCanvas definition={parsed||TEMPLATE}/>:<textarea spellCheck={false} value={source} onChange={e=>setSource(e.target.value)}/>}</main>
      <aside className="inspector"><Section title="Revision"><textarea className="note" placeholder="What changed?" value={note} onChange={e=>setNote(e.target.value)}/><button className="primary wide" onClick={save} disabled={!design||!parsed||!!busy}>Save immutable revision</button></Section><Section title="Native graph"><Row label="Board" value={parsed?`${mm(parsed.board.width_nm)} × ${mm(parsed.board.height_nm)} mm`:"—"}/><Row label="Layers" value={String(parsed?.board.layers.length||0)}/><Row label="Components" value={String(parsed?.components.length||0)}/><Row label="Nets" value={String(parsed?.nets.length||0)}/><Row label="Traces / vias" value={`${parsed?.traces.length||0} / ${parsed?.vias.length||0}`}/></Section><Section title="Validation"><div className={`status ${validation?.status||"idle"}`}>● {validation?.status||"not run"}{validation&&` · ${validation.errors} errors · ${validation.warnings} warnings`}</div>{validation?.report.checks.slice(0,12).map((c,i)=><div className="check" key={i} data-severity={c.severity}><b>{c.severity==="error"?"×":"!"}</b><span>{c.message}<small>{c.code}</small></span></div>)}</Section><Section title="Artifacts">{artifacts.map(a=><a className="artifact" key={a.id} href={url(`/artifacts/${a.id}/content`,projectId)}><b>{a.format}</b><span>{a.name}</span><small>{Math.max(1,Math.round(a.size_bytes/1024))}K</small></a>)}{!artifacts.length&&<p className="muted">Previews, BOMs, and releases appear here and in Storage.</p>}</Section></aside>
    </div><style>{styles}</style>
  </div>
}

function BoardCanvas({definition:d}:{definition:Definition}){const w=mm(d.board.width_nm),h=mm(d.board.height_nm);return <div className="viewport"><div className="board-meta">{w} × {h} mm · integer nm model</div><svg viewBox={`-2 -2 ${w+4} ${h+4}`}><rect className="board" width={w} height={h} rx="1"/>{d.traces.map(t=><polyline key={t.id} points={t.points.map(p=>`${mm(p.x_nm)},${mm(p.y_nm)}`).join(" ")} fill="none" stroke={t.layer==="F.Cu"?"#ff6b5e":"#63a7ff"} strokeWidth={mm(t.width_nm)} strokeLinecap="round" strokeLinejoin="round"/>)}{d.vias.map(v=><circle key={v.id} cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.diameter_nm)/2} fill="#d9b45b"/>)}{d.components.map(c=><g key={c.id} transform={`translate(${mm(c.position.x_nm)} ${mm(c.position.y_nm)}) rotate(${c.position.rotation_udeg/1e6})`}><rect className="component" x="-1.5" y="-1" width="3" height="2" rx=".2"/><text y="-1.4" textAnchor="middle">{c.designator}</text></g>)}</svg><div className="legend"><span><i className="front"/>F.Cu</span><span><i className="back"/>B.Cu</span><span><i className="part"/>components</span></div></div>}
function Label({children}:{children:React.ReactNode}){return <div className="label">{children}</div>}
function Section({title,children}:{title:string;children:React.ReactNode}){return <section><Label>{title}</Label>{children}</section>}
function Row({label,value}:{label:string;value:string}){return <div className="row"><span>{label}</span><b>{value}</b></div>}

const styles=`
.pcb-root{height:100%;display:flex;flex-direction:column;background:var(--color-bg,#0c1014);color:var(--color-text,#e8edf1);font-family:Inter,ui-sans-serif,sans-serif;overflow:hidden}.pcb-header{height:58px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--color-border,#273039)}.pcb-logo{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;background:#40c99a22;color:#53dfac;font-size:23px}.pcb-header h1{font-size:14px;margin:0}.pcb-header p{font-size:10px;color:#87929d;margin:2px 0 0}.grow{flex:1}.pcb-root button,.pcb-root input,.pcb-root textarea{font:inherit}.pcb-root button{border:1px solid #313c45;background:#151b21;color:#cdd5dc;border-radius:7px;padding:7px 10px;font-size:11px;cursor:pointer}.pcb-root button:hover{border-color:#53dfac88}.pcb-root button:disabled{opacity:.45;cursor:not-allowed}.pcb-root button.primary{background:#2fba89;color:#071611;border-color:#45dca7;font-weight:700}.progress{height:2px;background:#53dfac;animation:pulse 1s infinite}.error{padding:7px 16px;background:#ef5b5b1b;border-bottom:1px solid #ef5b5b55;color:#ff9090;font-size:11px}.pcb-grid{display:grid;grid-template-columns:220px minmax(360px,1fr) 300px;min-height:0;flex:1}.library,.inspector{padding:14px;border-right:1px solid #273039;overflow:auto}.inspector{border-right:0;border-left:1px solid #273039}.label{text-transform:uppercase;letter-spacing:.14em;font-size:9px;color:#7e8993;margin:2px 0 9px}.design-item{width:100%;display:flex!important;flex-direction:column;align-items:flex-start;margin-bottom:5px;background:transparent!important}.design-item[data-active=true]{background:#53dfac12!important;border-color:#53dfac88}.design-item strong{font-size:12px}.design-item small{font-size:9px;color:#7e8993;margin-top:3px}.muted{font-size:11px;color:#7e8993}.new{border-top:1px solid #273039;margin-top:18px;padding-top:15px}.pcb-root input,.note{box-sizing:border-box;width:100%;border:1px solid #313c45;border-radius:7px;background:#11171c;color:#dce4ea;padding:8px;font-size:11px;outline:none}.wide{width:100%;margin-top:8px}.workspace{display:flex;flex-direction:column;min-width:0;min-height:0}.tabs{height:43px;display:flex;align-items:center;gap:4px;padding:0 10px;border-bottom:1px solid #273039}.tabs button{border:0;background:transparent}.tabs button[data-active=true]{color:#53dfac;background:#53dfac13}.tabs code{font-size:9px;color:#77828c}.workspace>textarea{flex:1;resize:none;border:0;outline:0;background:#080d11;color:#bfced8;padding:18px;font:11px/1.55 ui-monospace,SFMono-Regular,monospace}.viewport{position:relative;display:grid;place-items:center;min-height:0;flex:1;overflow:hidden;background-color:#0b1115;background-image:linear-gradient(#1b252c55 1px,transparent 1px),linear-gradient(90deg,#1b252c55 1px,transparent 1px);background-size:20px 20px}.viewport svg{width:82%;height:82%;filter:drop-shadow(0 18px 30px #0008)}.board{fill:#123a32;stroke:#62deb1;stroke-width:.18}.component{fill:#ecf4f0;stroke:#18231e;stroke-width:.12}.viewport text{font:0.85px ui-monospace,monospace;fill:#f1fff8}.board-meta{position:absolute;top:12px;left:12px;background:#0a1015dd;border:1px solid #273039;border-radius:6px;padding:6px 8px;font:9px ui-monospace;color:#96a4ae}.legend{position:absolute;bottom:12px;right:12px;display:flex;gap:9px;background:#0a1015dd;border:1px solid #273039;border-radius:6px;padding:6px 8px;font-size:9px;color:#96a4ae}.legend span{display:flex;gap:4px;align-items:center}.legend i{width:7px;height:7px;border-radius:50%;background:#ff6b5e}.legend i.back{background:#63a7ff}.legend i.part{background:#ecf4f0}section{padding-bottom:16px;margin-bottom:16px;border-bottom:1px solid #273039}.note{min-height:58px;resize:vertical}.row{display:flex;justify-content:space-between;padding:4px 0;font-size:10px;color:#8f9ba5}.row b{color:#dce4ea;font-weight:500}.status{font-size:10px;padding:7px;border-radius:6px;background:#273039;color:#89959f}.status.passed{background:#40c99a18;color:#62e3b4}.status.warning{background:#e7b54b18;color:#f0c768}.status.failed{background:#ef5b5b18;color:#ff8585}.check{display:flex;gap:7px;margin-top:8px;font-size:10px;color:#adb7bf}.check>b{color:#e7b54b}.check[data-severity=error]>b{color:#ef5b5b}.check small{display:block;font:8px ui-monospace;color:#66727b;margin-top:2px}.artifact{display:flex;align-items:center;gap:7px;text-decoration:none;color:#cbd5dc;border:1px solid #2b353e;border-radius:6px;padding:7px;margin-bottom:5px;font-size:9px}.artifact b{width:28px;color:#53dfac;text-transform:uppercase}.artifact span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.artifact small{color:#78838c}@keyframes pulse{50%{opacity:.35}}@media(max-width:900px){.pcb-grid{grid-template-columns:180px 1fr}.inspector{display:none}.pcb-header p{display:none}}`;
